  async function readProducts(businessId, requestGeneration) { const result = await api('sales-products?businessId=' + encodeURIComponent(businessId)); if (requestGeneration !== generation || businessId !== state.business) return null; if (!Array.isArray(result.products) || (result.businessId && result.businessId !== businessId) || result.products.some(product => !product || typeof product.id !== 'string' || product.businessId !== businessId)) throw new Error('Product choices could not be safely matched to this business.'); return result.products; }
