    state.saving = true; state.error = ''; setDirty(true); redraw();
    try { const result = await api('sales-products', { action: 'save', businessId, ...(id ? { id } : {}), expectedRevision: request.expectedRevision, requestId: request.id, product: request.payload }); if (requestGeneration !== generation || businessId !== state.business) return false; if (result.success === false || !result.product || result.product.businessId !== businessId || !Array.isArray(result.product.history)) throw new Error(result.error || 'The product save result could not be confirmed.'); acceptProduct(result.product); if (typeof notice === 'function') notice('Product choice saved. Existing sale snapshots were not changed.'); return true; }
